package com.ganesh.bookshop.service; import com.ganesh.bookshop.model.Book; import com.ganesh.bookshop.repository.BookRepository; import org.springframework.stereotype.Service; import java.util.List; @Service public class BookService { private final BookRepository r; public BookService(BookRepository r){this.r=r;} public List<Book> all(String s){return s==null||s.isBlank()?r.findAll():r.findByTitleContainingIgnoreCaseOrAuthorContainingIgnoreCase(s,s);} public Book one(Long id){return r.findById(id).orElseThrow();} public Book save(Book b){return r.save(b);} public Book update(Long id,Book b){Book x=one(id);x.setTitle(b.getTitle());x.setAuthor(b.getAuthor());x.setCategory(b.getCategory());x.setPrice(b.getPrice());x.setStock(b.getStock());return r.save(x);} public void delete(Long id){r.deleteById(id);} }